# ----------------- Automated Green-API Diagnostic & Manual Webhook Repair -----------------
@app.get("/api/green_api_status")
def green_api_status():
    """Queries Green-API directly to see current webhook settings and instance state without rebooting."""
    base, token = get_green_api_base_and_token()
    if not base or not token:
        return {"error": "WHATSAPP_API_URL is missing or invalid format"}

    results = {}
    try:
        resp = http_session.get(f"{base}/getSettings/{token}", timeout=8)
        results["settings"] = resp.json() if resp.status_code == 200 else resp.text
    except Exception as e:
        results["settings_error"] = str(e)

    try:
        resp2 = http_session.get(f"{base}/getStateInstance/{token}", timeout=8)
        results["stateInstance"] = resp2.json() if resp2.status_code == 200 else resp2.text
    except Exception as e:
        results["state_error"] = str(e)

    return results

@app.get("/api/fix_green_api_webhook")
def fix_green_api_webhook():
    """Manually forces Green-API via API to set the Render webhook URL (Note: Green-API takes ~2-5 mins to apply)."""
    base, token = get_green_api_base_and_token()
    if not base or not token:
        return {"error": "WHATSAPP_API_URL is missing or invalid format"}

    render_url = (RENDER_EXTERNAL_URL or "https://ns-whatsapp-agent-1.onrender.com").strip().rstrip("/")
    target_webhook = f"{render_url}/webhook/whatsapp"
    payload = {
        "webhookUrl": target_webhook,
        "webhookUrlToken": "",
        "incomingWebhook": "yes",
        "outgoingMessageWebhook": "no",
        "outgoingAPIMessageWebhook": "no",
        "stateWebhook": "no"
    }
    try:
        resp = http_session.post(f"{base}/setSettings/{token}", json=payload, timeout=8)
        return {
            "action": "setSettings",
            "sent_payload": payload,
            "status_code": resp.status_code,
            "green_api_response": resp.json() if resp.status_code == 200 else resp.text
        }
    except Exception as e:
        return {"error": str(e)}

@app.get("/api/green_api_reboot")
def green_api_reboot():
    """Forces Green-API instance to reboot via API to unfreeze stuck starting/loading containers."""
    base, token = get_green_api_base_and_token()
    if not base or not token:
        return {"error": "WHATSAPP_API_URL is missing or invalid format"}
    try:
        resp = http_session.get(f"{base}/reboot/{token}", timeout=10)
        return {
            "action": "reboot",
            "status_code": resp.status_code,
            "response": resp.json() if resp.status_code == 200 else resp.text,
            "instructions": "המופע אותחל בהצלחה. המתן כדקה עד שתיים, ובדוק ב-Green-API אם הסטטוס הפך ל-authorized או שמופיע QR חדש לסריקה."
        }
    except Exception as e:
        return {"error": str(e)}

@app.get("/api/green_api_logout")
def green_api_logout():
    """Forces Green-API to drop the old stuck session and return to notAuthorized state so a new QR code appears."""
    base, token = get_green_api_base_and_token()
    if not base or not token:
        return {"error": "WHATSAPP_API_URL is missing or invalid format"}
    try:
        resp = http_session.get(f"{base}/logout/{token}", timeout=10)
        return {
            "action": "logout",
            "status_code": resp.status_code,
            "response": resp.json() if resp.status_code == 200 else resp.text,
            "instructions": "הסשן הישן נותק. המופע מתאפס ל-notAuthorized. כעת הגלגל המסתובב נעלם וניתן לסרוק QR חדש!"
        }
    except Exception as e:
        return {"error": str(e)}

@app.get("/api/green_api_qr")
def green_api_qr():
    """Fetches a fresh QR code from Green-API directly for quick re-authorization."""
    base, token = get_green_api_base_and_token()
    if not base or not token:
        return {"error": "WHATSAPP_API_URL is missing or invalid format"}
    try:
        resp = http_session.get(f"{base}/qr/{token}", timeout=10)
        if resp.status_code == 200:
            return resp.json()
        return {"status_code": resp.status_code, "response": resp.text}
    except Exception as e:
        return {"error": str(e)}

